	"sync"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookConfig stores the webhook configuration
type WebhookConfig struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigRequest represents the incoming request body
type ConfigRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigResponse represents the response body
type ConfigResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message"`
}

// Global storage for webhook configuration (in production, use a database)
var (
	webhookConfig WebhookConfig
	configMutex   sync.RWMutex
)

// ConfigureWebhook handles the POST request to configure a webhook
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req ConfigRequest

	// Parse the JSON body
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Invalid JSON body: " + err.Error(),
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Invalid URL format: " + err.Error(),
		})
	}

	// Ensure the URL has a valid scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "URL must use http or https scheme",
		})
	}

	// Create HTTP client with 3 second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send test GET request to validate the webhook URL
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Failed to validate webhook URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Check if the response status is acceptable (2xx or 3xx)
	if resp.StatusCode >= 400 {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Webhook URL validation failed with status: " + resp.Status,
		})
	}

	// Save the configuration
	configMutex.Lock()
	webhookConfig.WebhookURL = req.WebhookURL
	configMutex.Unlock()

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(ConfigResponse{
		Success: true,
		Message: "Webhook configured successfully",
	})
}

// GetWebhookConfig returns the current webhook configuration (helper endpoint)
func GetWebhookConfig(ctx *fiber.Ctx) error {
	configMutex.RLock()
	config := webhookConfig
	configMutex.RUnlock()

	return ctx.JSON(config)
}

func main() {
	app := fiber.New()

	// Configure webhook endpoint
	app.Post("/webhook/configure", ConfigureWebhook)

	// Optional: Get current configuration
	app.Get("/webhook/config", GetWebhookConfig)

	// Start the server
	app.Listen(":3000")
}

