// isPrivateIP checks if an IP address is private/internal
func isPrivateIP(ip net.IP) bool {
	if ip == nil {
		return true
	}

	// Check for loopback
	if ip.IsLoopback() {
		return true
	}

	// Check for unspecified (0.0.0.0 or ::)
	if ip.IsUnspecified() {
		return true
	}

	// Check for link-local
	if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}

	// Check for private networks
	if ip.IsPrivate() {
		return true
	}

	// Additional check for IPv4 mapped IPv6 addresses
	if ip4 := ip.To4(); ip4 != nil {
		// Check for 169.254.x.x (link-local)
		if ip4[0] == 169 && ip4[1] == 254 {
			return true
		}
	}

	return false
}

// isAllowedHost validates that the host resolves to a public IP
func isAllowedHost(hostname string) (bool, error) {
	// Resolve the hostname
	ips, err := net.LookupIP(hostname)
	if err != nil {
		return false, fmt.Errorf("failed to resolve hostname: %v", err)
	}

	// Check all resolved IPs
	for _, ip := range ips {
		if isPrivateIP(ip) {
			return false, fmt.Errorf("hostname resolves to private/internal IP address")
		}
	}

	return true, nil
}

