)

// WebhookConfig holds the webhook configuration
type WebhookConfig struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigResponse represents the response structure
type ConfigResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message"`
	URL     string `json:"url,omitempty"`
}

// Global storage for webhook configuration (thread-safe)
var (
	savedWebhookURL string
	configMutex     sync.RWMutex
)

// ConfigureWebhook handles POST requests to configure a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON body
	var config WebhookConfig
	if err := ctx.BodyParser(&config); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Invalid JSON body: " + err.Error(),
		})
	}

	// Validate that webhook_url is provided
	if config.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(config.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Invalid URL format: " + err.Error(),
		})
	}

	// Ensure the URL has a valid scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "URL must use http or https scheme",
		})
	}

	// Create HTTP client with 3 second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a test GET request to validate the webhook URL
	resp, err := client.Get(config.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Failed to validate webhook URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Check if the response status is acceptable (2xx or 3xx)
	if resp.StatusCode >= 400 {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Webhook URL validation failed with status: " + resp.Status,
		})
	}

	// Save the configuration
	configMutex.Lock()
	savedWebhookURL = config.WebhookURL
	configMutex.Unlock()

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(ConfigResponse{
		Success: true,
		Message: "Webhook configured successfully",
		URL:     config.WebhookURL,
	})
}

// GetWebhookConfig returns the current webhook configuration
func GetWebhookConfig(ctx *fiber.Ctx) error {
	configMutex.RLock()
	currentURL := savedWebhookURL
	configMutex.RUnlock()

	if currentURL == "" {
		return ctx.Status(fiber.StatusNotFound).JSON(ConfigResponse{
			Success: false,
			Message: "No webhook configured",
		})
	}

	return ctx.Status(fiber.StatusOK).JSON(ConfigResponse{
		Success: true,
		Message: "Webhook configuration retrieved",
		URL:     currentURL,
	})
}

func main() {
	app := fiber.New()

	// Configure webhook endpoint
	app.Post("/webhook/configure", ConfigureWebhook)

	// Get current webhook configuration
	app.Get("/webhook/config", GetWebhookConfig)

	// Start the server
	app.Listen(":3000")
}

